code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    vector<int> counts(26, 0);
    for (char ch : s) {
        counts[ch - 'a']++;
    }
    int best = 0;
    for (int i = 0; i < 26; i++) {
        if (counts[i] > counts[best]) {
            best = i;
        }
    }
    cout << (char) ('a' + best) << " " << counts[best] << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) {
            counts[s.charAt(i) - 'a']++;
        }
        int best = 0;
        for (int i = 0; i < 26; i++) {
            if (counts[i] > counts[best]) {
                best = i;
            }
        }
        System.out.println((char) ('a' + best) + " " + counts[best]);
    }
}
